<!doctype html><html><head><meta charset="utf-8"><style>
@page{margin:26px 30px}body{font-family:Helvetica,sans-serif;color:#18212f;font-size:10px;line-height:1.45}.hero{background:#111827;color:#fff;padding:18px 20px;border-radius:8px}.hero h1{font-size:21px;margin:5px 0}.eyebrow{color:#93c5fd;font-size:8px;font-weight:bold;letter-spacing:1px;text-transform:uppercase}.meta{color:#cbd5e1;font-size:9px}.section{margin-top:18px}.section h2{border-left:4px solid #2563eb;font-size:14px;padding-left:8px}.summary,.costs{border-collapse:collapse;width:100%}.summary td{border:1px solid #bfdbfe;background:#eff6ff;padding:10px;width:33%}.label{color:#475569;font-size:8px;text-transform:uppercase}.value{font-size:15px;font-weight:bold}.costs th,.costs td{border-bottom:1px solid #e5e7eb;padding:7px;text-align:left}.right{text-align:right!important}.offer{border:1px solid #cbd5e1;border-radius:7px;margin:10px 0;padding:10px}.provider{color:#2563eb;font-size:8px;font-weight:bold;text-transform:uppercase}.recommendation{background:#ecfdf5;border-left:3px solid #10b981;padding:8px}.empty{background:#fffbeb;border:1px solid #fde68a;padding:10px}.foot{color:#64748b;font-size:8px;margin-top:18px}
</style></head><body><div class="hero"><div class="eyebrow">Personalized savings planner</div><h1>Savings Offers &amp; Shopping Advice</h1><p>Period: <?=e($from->format('d M Y'))?> – <?=e($to->format('d M Y'))?> | Location: <?=e($location)?></p></div><div class="section"><table class="summary"><tr><td><div class="label">Total spending</div><div class="value">BDT <?=e(number_format($total,0))?></div></td><td><div class="label">Expense categories</div><div class="value"><?=e(count($spending))?></div></td><td><div class="label">Average period</div><div class="value"><?=e($months)?> month(s)</div></td></tr></table></div><div class="section"><h2>Your spending priorities</h2><table class="costs"><tr><th>Category</th><th class="right">Period spending</th><th class="right">Monthly average</th></tr><?php foreach(array_slice($spending,0,8) as $row):?><tr><td><?=e($row['category'])?></td><td class="right">BDT <?=e(number_format((float)$row['amount'],0))?></td><td class="right">BDT <?=e(number_format((float)$row['amount']/max(1,$months),0))?></td></tr><?php endforeach;?></table></div><div class="section"><h2>Offers and recommendations</h2><?php if($offers===[]):?><div class="empty"><?=e($searchStatus?:'No live offers found.')?></div><?php else:?><?php foreach($offers as $index=>$offer):?><div class="offer"><div class="provider">Offer <?=e($index+1)?> · <?=e($offer['provider'])?></div><h3><?=e($offer['focus'])?></h3><p><?=e($offer['source'])?></p><div class="recommendation"><b>Recommendation</b><br><?=e($offer['recommendation'])?></div></div><?php endforeach;?><?php endif;?></div><p class="foot">Verify offer terms and eligibility at the source before purchasing.</p></body></html>
